PACKAGE BODY math_pkg IS
    PROCEDURE is_odd(n NUMBER) IS
    BEGIN
        IF n = 0 THEN NULL; ELSE is_even(n - 1); END IF; -- is_even이 아직 아래에 정의됨
    END;
    PROCEDURE is_even(n NUMBER) IS
    BEGIN
        IF n = 0 THEN NULL; ELSE is_odd(n - 1); END IF;
    END;
END;
